    // leaves
    leafXs.forEach(function (L) {
      if (L.dots) { ellipsisH(gTree, L.x, leafYy); return; }
      node(gTree, 'c', L.x, leafYy, {
        accent: state.active === k, halo: true, tip: levelTip(k, true),
        onClick: function () { setActive(k); }
      });
    });

    // brace + n label
    var bx1 = leafXs[0].x - 30, bx2 = leafXs[leafXs.length - 1].x + 30;
    brace(gTree, bx1, bx2, leafYy + 36, 15);
    txt(gTree, 'n', (bx1 + bx2) / 2, leafYy + 100, 26);
    hit(gTree, (bx1 + bx2) / 2, leafYy + 70, bx2 - bx1, 80,
      'The bottom row holds n = ' + nv + ' leaves, each of cost c \u2192 cn total',
      function () { setActive(k); });

    // lg n arrow
    vArrow(gTree, 52, rowYs[0] - 10, leafYy + 12);
    gTree.rect(70, 66).move(17, 902).fill('#fff');
    txt(gTree, 'lg', 42, 932, 26, { anchor: 'end', upright: true });
    txt(gTree, 'n', 50, 932, 26, { anchor: 'start' });
    if (state.overlay) txt(gTree, '= ' + k, 52, 978, 15, { fill: ACCENT_DK, upright: true });
    hit(gTree, 52, 930, 76, 700, 'Tree height = lg n = ' + k + ' (so lg n + 1 = ' + (k + 1) + ' levels)', null);

    // right cost column
    for (i2 = 0; i2 <= topDrawn; i2++) {
      var cntR = Math.pow(2, i2);
      costRow(i2, rowYs[i2], xAt(i2, cntR - 1) + halfW(costLabel(i2), 26) + 22, false);
    }
    if (!full) ellipsisV(gTree, COLX, 1120);
    costRow(k, leafYy, leafXs[leafXs.length - 1].x + 26, true);

    // rule + total
    gTree.line(862, 1342, 992, 1342).stroke({ color: '#000', width: 1.8 });
    txt(gTree, 'Total:', 792, 1392, 24, { anchor: 'end', upright: true });
    txt(gTree, 'cn lg n + cn', 800, 1392, 24, { anchor: 'start' });
    hit(gTree, 880, 1392, 240, 46,
      (k + 1) + ' levels \u00d7 cn = cn lg n + cn = \u0398(n lg n)', function () {
        showPopup('Adding the column',
          'There are lg n = ' + k + ' internal levels plus one leaf level, and every one of them costs exactly cn. So T(n) = cn\u00b7lg n + cn = \u0398(n lg n).');
      });

    txt(gTree, '(d)', 415, 1400, 26, { upright: true });
  }

  /* ---------- render ---------- */
  function render() {
    gTree.clear(); gTreeBG.clear();
    for (var i = 0; i < hlRects.length; i++) hlRects[i].opacity(state.stage === i ? 1 : 0);
    drawTree();
    var btn = document.getElementById('stageBtn');
    if (btn) btn.textContent = 'Expand \u25b8 now at ' + stageNames[state.stage];
    var ro = document.getElementById('readout');
    if (ro) {
      var nv = Math.pow(2, state.k);
      ro.innerHTML = 'n = ' + nv + ' &middot; lg n = ' + state.k + ' &middot; levels = lg n + 1 = ' + (state.k + 1) +
        ' &middot; each level costs cn &rarr; total = ' + (state.k + 1) + 'cn';
    }
  }

  /* ---------- controls ---------- */
  function setStage(s) { state.stage = s; state.active = -1; hidePopup(); render(); }
  window.setStage = setStage;
  window.trigger_expandStage = function () { setStage((state.stage + 1) % 4); };
  window.update_problemSize = function (v) { state.k = Math.round(v); state.active = -1; render(); };
  window.toggle_levelCosts = function (on) { state.overlay = !!on; render(); };

  /* ---------- demo player ---------- */
  var steps = [
    { title: 'The printed figure', narration: 'Recursion tree for T(n) = 2T(n/2) + cn. Stages (a)\u2013(c) show the substitution unfolding; (d) is the finished tree. Use the controls below, or step through the guided tour.', state: { expandStage: '(d) full tree', levelCosts: 'off', problemSize: 16 } },
    { title: 'Start with the recurrence', narration: 'The figure begins with a single unresolved term, T(n), for merge sort\u2019s running time defined by T(n) = 2T(n/2) + cn.', state: { expandStage: '(a) T(n)', levelCosts: 'off', problemSize: 16 } },
    { title: 'One split', narration: 'Replace T(n) by its definition: a root of cost cn with two children that are still unresolved, T(n/2) and T(n/2).', state: { expandStage: '(b) one split', levelCosts: 'off', problemSize: 16 } },
    { title: 'Split again', narration: 'Apply the same substitution to each T(n/2). The two children become cost nodes cn/2, each spawning two T(n/4) terms \u2014 the pattern is self-similar.', state: { expandStage: '(c) two splits', levelCosts: 'off', problemSize: 16 } },
    { title: 'The full tree', narration: 'Continue until every leaf is a base case of cost c. There are n leaves across the bottom, and the height marker on the left reads lg n.', state: { expandStage: '(d) full tree', levelCosts: 'off', problemSize: 16 } },
    { title: 'Every level costs cn', narration: 'Turn on the level-cost overlay: level i has 2^i nodes of cost cn/2^i, so each row sums to exactly cn \u2014 the dotted arrows on the right all point to the same value.', state: { expandStage: '(d) full tree', levelCosts: 'on', problemSize: 16 } },
    { title: 'Change n and watch the height', narration: 'Grow n to 64: the leaf row widens, the tree gains levels, and the left arrow still reads lg n \u2014 the only thing that changed is how many identical cn rows there are.', state: { expandStage: '(d) full tree', levelCosts: 'on', problemSize: 64 } },
    { title: 'Add the column', narration: 'With lg n levels of internal cost cn plus the leaf level of cost cn, the total is cn lg n + cn = \u0398(n lg n).', state: { expandStage: '(d) full tree', levelCosts: 'on', problemSize: 32 } }
  ];
  var cur = 0;

  function applyStep(idx) {
    cur = Math.max(0, Math.min(steps.length - 1, idx));
    var st = steps[cur].state;
    state.stage = stageNames.indexOf(st.expandStage);
    var k = Math.round(Math.log(st.problemSize) / Math.LN2);
    state.k = k;
    document.getElementById('problemSizeInput').value = k;
    document.getElementById('problemSizeVal').value = st.problemSize;
    state.overlay = (st.levelCosts === 'on');
    document.getElementById('levelCostsInput').checked = state.overlay;
    state.active = -1;
    hidePopup();
    document.getElementById('demoNarration').innerHTML = '<b>' + steps[cur].title + '</b><br>' + steps[cur].narration;
    document.getElementById('stepLabel').textContent = cur === 0 ? 'overview' : ('step ' + cur + ' / ' + (steps.length - 1));
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  drawTop();
  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

