         oninput="document.getElementById('problemSizeVal').value=Math.pow(2,+this.value);update_problemSize(+this.value)">
</label>
<label><input id="levelCostsInput" type="checkbox" onchange="toggle_levelCosts(this.checked)"> Level-cost overlay</label>
<span style="font-size:11px;color:#666;line-height:1.45">Click any level — its nodes or its <i>cn</i> on the right — to see 2<sup>i</sup> × cn/2<sup>i</sup> = cn.</span>
<span id="readout" style="font-size:11px;color:#333;line-height:1.45"></span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var W = 1240, H = 1010;
  var ACCENT = '#e09b2d', ACCENT_DK = '#a8650a', GHOST = '#8a8f95';
  var SERIF = 'Georgia, "Times New Roman", Times, serif';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var gTopHL = draw.group();
  var gTop = draw.group();
  var gTreeBG = draw.group();
  var gTree = draw.group();

  /* ---------- helpers ---------- */
  function txt(g, s, x, y, size, o) {
    o = o || {};
    var t = g.plain(s)
      .font({ family: SERIF, size: size, anchor: o.anchor || 'middle', style: o.upright ? 'normal' : 'italic' })
      .attr({ x: x, y: y, 'dominant-baseline': 'central' })
      .fill(o.fill || '#000');
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
    return t;
  }
  function hit(g, x, y, w, h, tip, onClick) {
    var r = g.rect(w, h).center(x, y).fill('#fff').opacity(0).attr('pointer-events', 'all');
    r.css('cursor', 'pointer');
    r.on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { hideTooltip(); if (onClick) onClick(); });
    return r;
  }
  function edge(g, px, py, cx, cy, o) {
    o = o || {};
    var dx = cx - px, dy = cy - py;
    g.line(px + dx * 0.16, py + dy * 0.16, cx - dx * 0.18, cy - dy * 0.18)
      .stroke({ color: o.color || '#000', width: o.width || 1.8 });
  }
  function dottedArrow(g, x1, x2, y, color) {
    if (x2 - x1 < 30) return;
    g.line(x1, y, x2 - 13, y).stroke({ color: color, width: 3.2, dasharray: '2,7', linecap: 'round' });
    g.polygon((x2 - 13) + ',' + (y - 7) + ' ' + x2 + ',' + y + ' ' + (x2 - 13) + ',' + (y + 7)).fill(color);
  }
  function ellipsisH(g, x, y, col) { [-18, 0, 18].forEach(function (d) { g.circle(8).center(x + d, y).fill(col || '#000'); }); }
  function ellipsisV(g, x, y) { [-26, 0, 26].forEach(function (d) { g.circle(8).center(x, y + d).fill('#000'); }); }
  function brace(g, x1, x2, y, d) {
    var mid = (x1 + x2) / 2, r = 16;
    var p = 'M' + x1 + ',' + y + ' q0,' + d + ' ' + r + ',' + d +
      ' H' + (mid - r) + ' q' + r + ',0 ' + r + ',' + d +
      ' q0,-' + d + ' ' + r + ',-' + d +
      ' H' + (x2 - r) + ' q' + r + ',0 ' + r + ',-' + d;
    g.path(p).fill('none').stroke({ color: '#000', width: 1.8, linejoin: 'round' });
  }
  function vArrow(g, x, y1, y2) {
    g.line(x, y1 + 10, x, y2 - 10).stroke({ color: '#000', width: 2.2 });
    g.polygon(x + ',' + y1 + ' ' + (x - 10) + ',' + (y1 + 20) + ' ' + (x + 10) + ',' + (y1 + 20)).fill('#000');
    g.polygon(x + ',' + y2 + ' ' + (x - 10) + ',' + (y2 - 20) + ' ' + (x + 10) + ',' + (y2 - 20)).fill('#000');
  }
  function halfW(label, size) { return label.length * size * 0.26 + 8; }
  function lerp(t, a, b) { return a + (b - a) * t; }

  var FS = 32, FS_SM = 28;

  function node(g, label, x, y, o) {
    o = o || {};
    var size = o.size || FS;
    txt(g, label, x, y, size, { fill: o.accent ? ACCENT_DK : '#000', halo: o.halo !== false });
    hit(g, x, y, label.length * size * 0.52 + 20, size + 16, o.tip || label, o.onClick);
  }

  /* ---------- geometry ---------- */
  var X0 = 200, X1 = 900;
  function xAt(i, j) { return X0 + (X1 - X0) * ((j + 0.5) / Math.pow(2, i)); }
  var YTOP = 442, YLEAF = 832;
  var COLX = 1135, ARROWEND = 1080;
  var STAGEY = [442, 604, 766];

  var stageNames = ['(a) T(n)', '(b) one split', '(c) two splits', '(d) full tree'];
  var state = { stage: 3, k: 4, overlay: false, active: -1 };

  function costLabel(i) { return i === 0 ? 'cn' : 'cn/' + Math.pow(2, i); }
  function termLabel(i) { return i === 0 ? 'T(n)' : 'T(n/' + Math.pow(2, i) + ')'; }

  /* ---------- static stages (a) (b) (c) ---------- */
  var hlRects = [];
  function mkHL(x, y, w, h) {
    var r = gTopHL.rect(w, h).move(x, y).radius(12)
      .fill({ color: ACCENT, opacity: 0.15 }).stroke({ color: ACCENT, width: 1.8 }).opacity(0);
    hlRects.push(r); return r;
  }
  function drawTop() {
    mkHL(8, 8, 96, 56); mkHL(140, 8, 330, 212); mkHL(530, 8, 700, 330);

    // (a)
    node(gTop, 'T(n)', 56, 36, { tip: '(a) The bare recurrence term T(n)', onClick: function () { setStage(0); } });
    txt(gTop, '(a)', 56, 366, 30, { upright: true });

    // (b)
    edge(gTop, 300, 36, 216, 178); edge(gTop, 300, 36, 386, 178);
    node(gTop, 'cn', 300, 36, { tip: '(b) Root cost cn — the merge step on n elements' });
    node(gTop, 'T(n/2)', 216, 178, { size: FS_SM, tip: 'Still-unresolved subproblem of size n/2' });
    node(gTop, 'T(n/2)', 386, 178, { size: FS_SM, tip: 'Still-unresolved subproblem of size n/2' });
    txt(gTop, '(b)', 300, 366, 30, { upright: true });
    hit(gTop, 305, 114, 330, 212, '(b) One substitution: T(n) = cn + 2T(n/2)', function () { setStage(1); });

    // (c)  — widened so the four T(n/4) labels keep clear gaps
    edge(gTop, 860, 36, 690, 166); edge(gTop, 860, 36, 1030, 166);
    edge(gTop, 690, 166, 605, 300); edge(gTop, 690, 166, 775, 300);
    edge(gTop, 1030, 166, 945, 300); edge(gTop, 1030, 166, 1115, 300);
    node(gTop, 'cn', 860, 36, { tip: 'Root cost cn' });
    node(gTop, 'cn/2', 690, 166, { tip: 'Resolved cost cn/2 at this node' });
    node(gTop, 'cn/2', 1030, 166, { tip: 'Resolved cost cn/2 at this node' });
    [605, 775, 945, 1115].forEach(function (x) {
      node(gTop, 'T(n/4)', x, 300, { size: FS_SM, tip: 'Still-unresolved subproblem of size n/4' });
    });
    txt(gTop, '(c)', 860, 366, 30, { upright: true });
    hit(gTop, 880, 170, 700, 326, '(c) Substitute again: each T(n/2) becomes cn/2 + 2T(n/4)', function () { setStage(2); });
  }

  /* ---------- level focus ---------- */
  function setActive(i) {
    state.active = (state.active === i) ? -1 : i;
    render();
    if (state.active < 0) { hidePopup(); return; }
    var nv = Math.pow(2, state.k), cnt = Math.pow(2, i);
    if (i === state.k) {
      showPopup('Leaf level (level ' + i + ')',
        'The bottom level holds n = ' + nv + ' leaves, each a base case of cost c. Together they cost n\u00b7c = cn — exactly the same as every internal level above them.');
    } else {
      showPopup('Level ' + i,
        'Level ' + i + ' has 2^' + i + ' = ' + cnt + ' nodes, each costing cn/' + cnt + '. Multiplying gives ' + cnt + ' \u00d7 cn/' + cnt + ' = cn. The doubling of nodes exactly cancels the halving of cost, so every level sums to cn.');
    }
  }
  function levelTip(i, kind) {
    var cnt = Math.pow(2, i);
    if (kind === 'leaf') return 'Leaf level: n = ' + Math.pow(2, state.k) + ' nodes of cost c \u2192 cn total (click for detail)';
    if (kind === 'ghost') return 'Omitted level ' + i + ': ' + cnt + ' nodes of cost cn/' + cnt + ' \u2192 cn total (click for detail)';
    return 'Level ' + i + ': ' + cnt + ' node' + (cnt > 1 ? 's' : '') + ' of cost cn/' + cnt + ' \u2192 cn total (click for detail)';
  }
  function band(y, strong) {
    gTreeBG.rect(1090, 60).move(140, y - 30).radius(10)
      .fill({ color: ACCENT, opacity: strong ? 0.22 : 0.07 });
  }
  function costRow(i, y, xStart, kind) {
    var act = state.active === i;
    if (act) band(y, true); else if (state.overlay) band(y, false);
    var col = act ? ACCENT_DK : (kind === 'ghost' ? GHOST : '#000');
    dottedArrow(gTree, xStart, ARROWEND, y, col);
    txt(gTree, 'cn', COLX, y, FS, { fill: col, halo: true });
    if (state.overlay || act) {
      var cnt = Math.pow(2, i);
      var s = (kind === 'leaf') ? (Math.pow(2, state.k) + ' \u00d7 c') : (cnt + ' \u00d7 cn/' + cnt);
      txt(gTree, s, COLX, y + 28, 18, { fill: act ? ACCENT_DK : GHOST, upright: true, halo: true });
    }
    hit(gTree, COLX, y, 170, 54, levelTip(i, kind), function () { setActive(i); });
  }

  /* ---------- stage (d) region ---------- */
  function drawTree() {
    var stg = state.stage, k = state.k, i, j;

    if (stg === 0) {
      node(gTree, 'T(n)', xAt(0, 0), STAGEY[0], {
        accent: state.active === 0,
        tip: 'Unresolved: the whole problem costs T(n) = 2T(n/2) + cn',
        onClick: function () { setActive(0); }
      });
      return;
    }

    if (stg < 3) {
      for (i = 0; i <= stg; i++) {
        var cnt = Math.pow(2, i), y = STAGEY[i];
        if (state.active === i) band(y, true);
        if (i < stg) {
          for (j = 0; j < cnt; j++) {
            edge(gTree, xAt(i, j), y, xAt(i + 1, 2 * j), STAGEY[i + 1]);
            edge(gTree, xAt(i, j), y, xAt(i + 1, 2 * j + 1), STAGEY[i + 1]);
          }
        }
        for (j = 0; j < cnt; j++) {
          (function (i2, j2) {
            var x = xAt(i2, j2);
            if (i2 < stg) {
              node(gTree, costLabel(i2), x, STAGEY[i2], {
                accent: state.active === i2, tip: levelTip(i2, 'level'),
                onClick: function () { setActive(i2); }
              });
            } else {
              node(gTree, termLabel(i2), x, STAGEY[i2], {
                size: i2 >= 2 ? FS_SM : FS, accent: state.active === i2,
                tip: 'Unresolved subproblem — press "Expand" to substitute its definition',
                onClick: function () { setActive(i2); }
              });
            }
          })(i, j);
        }
        if (i < stg) costRow(i, y, xAt(i, cnt - 1) + halfW(costLabel(i), FS) + 26, 'level');
      }
      return;
    }

    /* ---- full tree ---- */
    var nv = Math.pow(2, k);
    var gap = (YLEAF - YTOP) / k, rowY = [];
    for (i = 0; i <= k; i++) rowY.push(YTOP + gap * i);
    var complete = (k <= 3);
    var realTop = complete ? k - 1 : 2;
    var showGhosts = !complete && (state.overlay || k !== 4);

    // edges between real internal levels
    for (i = 0; i < realTop; i++) {
      for (j = 0; j < Math.pow(2, i); j++) {
        edge(gTree, xAt(i, j), rowY[i], xAt(i + 1, 2 * j), rowY[i + 1]);
        edge(gTree, xAt(i, j), rowY[i], xAt(i + 1, 2 * j + 1), rowY[i + 1]);
      }
    }

    var leaves = [];
    if (complete) {
      for (j = 0; j < Math.pow(2, k - 1); j++) {
        edge(gTree, xAt(k - 1, j), rowY[k - 1], xAt(k, 2 * j), rowY[k]);
        edge(gTree, xAt(k - 1, j), rowY[k - 1], xAt(k, 2 * j + 1), rowY[k]);
      }
      for (j = 0; j < nv; j++) leaves.push({ x: xAt(k, j), dots: false });
    } else {
      var sy0 = rowY[2] + 22, sy1 = rowY[2] + Math.min(82, gap * 0.72);
      for (j = 0; j < 8; j++) {
        var px = xAt(2, Math.floor(j / 2)), cx = xAt(3, j);
        gTree.line(lerp(0.06, px, cx), lerp(0.06, sy0, sy1), lerp(0.50, px, cx), lerp(0.50, sy0, sy1))
          .stroke({ color: '#000', width: 1.8 });
        gTree.line(lerp(0.58, px, cx), lerp(0.58, sy0, sy1), lerp(0.94, px, cx), lerp(0.94, sy0, sy1))
          .stroke({ color: '#000', width: 1.6, dasharray: '7,7' });
        var isDots = (j === 5);
        if (!isDots) {
          // true dashed drop-line down to the leaf row (omitted-level cue)
          gTree.line(cx, sy1 + 16, cx, rowY[k] - 28)
            .stroke({ color: '#000', width: 1.7, dasharray: '6,6', linecap: 'butt' });
        }
        leaves.push({ x: cx, dots: isDots });
      }
      // omitted (ghost) levels 3 .. k-1
      if (showGhosts) {
        for (i = 3; i <= k - 1; i++) {
          if (state.active === i) band(rowY[i], true); else if (state.overlay) band(rowY[i], false);
          var gcol = state.active === i ? ACCENT_DK : GHOST;
          for (j = 0; j < 8; j++) gTree.circle(10).center(xAt(3, j), rowY[i]).fill(gcol).opacity(0.8);
        }
      }
    }

    // band highlights for real levels + leaf level
    for (i = 0; i <= realTop; i++) {
      if (state.active === i) band(rowY[i], true); else if (state.overlay) band(rowY[i], false);
    }
    if (state.active === k) band(rowY[k], true); else if (state.overlay) band(rowY[k], false);

    // internal cost nodes
    for (i = 0; i <= realTop; i++) {
      for (j = 0; j < Math.pow(2, i); j++) {
        (function (i2, j2) {
          node(gTree, costLabel(i2), xAt(i2, j2), rowY[i2], {
            accent: state.active === i2, tip: levelTip(i2, 'level'),
            onClick: function () { setActive(i2); }
          });
        })(i, j);
      }
    }

    // leaves
    leaves.forEach(function (L) {
      if (L.dots) { ellipsisH(gTree, L.x, rowY[k]); return; }
      node(gTree, 'c', L.x, rowY[k], {
        accent: state.active === k, tip: levelTip(k, 'leaf'),
        onClick: function () { setActive(k); }
      });
    });

    // brace + n
    var bx1 = leaves[0].x - 30, bx2 = leaves[leaves.length - 1].x + 30;
    brace(gTree, bx1, bx2, rowY[k] + 38, 16);
    txt(gTree, 'n', (bx1 + bx2) / 2, rowY[k] + 94, FS);
    if (state.overlay) txt(gTree, '= ' + nv, (bx1 + bx2) / 2 + 42, rowY[k] + 94, 20, { fill: ACCENT_DK, upright: true, anchor: 'start' });
    hit(gTree, (bx1 + bx2) / 2, rowY[k] + 68, bx2 - bx1, 76,
      'The bottom row holds n = ' + nv + ' leaves, each of cost c \u2192 cn total', function () { setActive(k); });

    // lg n arrow (label sits to the LEFT of the shaft)
    vArrow(gTree, 112, rowY[0] - 16, rowY[k] + 18);
    var ly = (rowY[0] + rowY[k]) / 2;
    gTree.rect(92, 58).center(58, ly).fill('#fff');
    txt(gTree, 'lg', 62, ly, FS, { anchor: 'end', upright: true });
    txt(gTree, 'n', 70, ly, FS, { anchor: 'start' });
    if (state.overlay) txt(gTree, '= ' + k, 58, ly + 36, 20, { fill: ACCENT_DK, upright: true });
    hit(gTree, 78, ly, 110, rowY[k] - rowY[0] + 40,
      'Tree height = lg n = ' + k + ', so there are lg n + 1 = ' + (k + 1) + ' levels', null);

    // right-hand cost column
    for (i = 0; i <= realTop; i++) {
      costRow(i, rowY[i], xAt(i, Math.pow(2, i) - 1) + halfW(costLabel(i), FS) + 26, 'level');
    }
    if (!complete) {
      if (showGhosts) { for (i = 3; i <= k - 1; i++) costRow(i, rowY[i], 930, 'ghost'); }
      else {
        var my = (rowY[2] + rowY[k]) / 2;
        ellipsisV(gTree, COLX, my);
        hit(gTree, COLX, my, 120, 120, 'The levels between are omitted — each of them also costs cn', null);
      }
    }
    costRow(k, rowY[k], leaves[leaves.length - 1].x + 30, 'leaf');

    // rule + total
    gTree.line(1050, 896, 1212, 896).stroke({ color: '#000', width: 2 });
    txt(gTree, 'Total:', 958, 950, 29, { anchor: 'end', upright: true });
    txt(gTree, 'cn lg n + cn', 970, 950, 29, { anchor: 'start' });
    hit(gTree, 1050, 950, 290, 54,
      (k + 1) + ' levels \u00d7 cn = cn lg n + cn = \u0398(n lg n)', function () {
        showPopup('Adding the column',
          'There are lg n = ' + k + ' internal levels plus one leaf level, and every one of them costs exactly cn. So T(n) = cn\u00b7lg n + cn = \u0398(n lg n).');
      });

    // (d) caption — bottom-left, well clear of the brace label "n"
    txt(gTree, '(d)', 200, 972, 30, { upright: true });
  }

  /* ---------- render ---------- */
  function render() {
    gTree.clear(); gTreeBG.clear();
    for (var i = 0; i < hlRects.length; i++) hlRects[i].opacity(state.stage === i ? 1 : 0);
    drawTree();
    var btn = document.getElementById('stageBtn');
    if (btn) btn.textContent = 'Expand \u25b8 now at ' + stageNames[state.stage];
    var ro = document.getElementById('readout');
    if (ro) {
      var nv = Math.pow(2, state.k);
      ro.innerHTML = '<i>n</i> = ' + nv + ' &middot; lg <i>n</i> = ' + state.k + ' &middot; levels = lg <i>n</i> + 1 = ' + (state.k + 1) +
        ' &middot; each level costs <i>cn</i> &rarr; total = ' + (state.k + 1) + '<i>cn</i>';
    }
  }

  /* ---------- controls ---------- */
  function setStage(s) { state.stage = s; state.active = -1; hidePopup(); render(); }
  window.setStage = setStage;
  window.trigger_expandStage = function () { setStage((state.stage + 1) % 4); };
  window.update_problemSize = function (v) { state.k = Math.round(v); state.active = -1; hidePopup(); render(); };
  window.toggle_levelCosts = function (on) { state.overlay = !!on; render(); };

  /* ---------- demo player ---------- */
  var steps = [
    { title: 'The printed figure', narration: 'Recursion tree for T(n) = 2T(n/2) + cn. Stages (a)\u2013(c) show the substitution unfolding; (d) is the finished tree. Use the controls, or step through the guided tour.', state: { expandStage: '(d) full tree', levelCosts: 'off', problemSize: 16 } },
    { title: 'Start with the recurrence', narration: 'The figure begins with a single unresolved term, T(n), for merge sort\u2019s running time defined by T(n) = 2T(n/2) + cn.', state: { expandStage: '(a) T(n)', levelCosts: 'off', problemSize: 16 } },
    { title: 'One split', narration: 'Replace T(n) by its definition: a root of cost cn with two children that are still unresolved, T(n/2) and T(n/2).', state: { expandStage: '(b) one split', levelCosts: 'off', problemSize: 16 } },
    { title: 'Split again', narration: 'Apply the same substitution to each T(n/2). The two children become cost nodes cn/2, each spawning two T(n/4) terms \u2014 the pattern is self-similar.', state: { expandStage: '(c) two splits', levelCosts: 'off', problemSize: 16 } },
    { title: 'The full tree', narration: 'Continue until every leaf is a base case of cost c. There are n leaves across the bottom, and the height marker on the left reads lg n.', state: { expandStage: '(d) full tree', levelCosts: 'off', problemSize: 16 } },
    { title: 'Every level costs cn', narration: 'Turn on the level-cost overlay: level i has 2^i nodes of cost cn/2^i, so each row sums to exactly cn. The omitted levels appear as grey rows \u2014 they each cost cn too.', state: { expandStage: '(d) full tree', levelCosts: 'on', problemSize: 16 } },
    { title: 'Change n and watch the height', narration: 'Grow n to 64: the tree gains levels (two more grey rows appear, each worth cn) while the left arrow still reads lg n. Slide down to n = 8 or 4 to see the whole tree drawn out.', state: { expandStage: '(d) full tree', levelCosts: 'on', problemSize: 64 } },
    { title: 'Add the column', narration: 'With lg n levels of internal cost cn plus the leaf level of cost cn, the total is cn lg n + cn = \u0398(n lg n).', state: { expandStage: '(d) full tree', levelCosts: 'on', problemSize: 32 } }
  ];
  var cur = 0;

  function applyStep(idx) {
    cur = Math.max(0, Math.min(steps.length - 1, idx));
    var st = steps[cur].state;
    state.stage = stageNames.indexOf(st.expandStage);
    var k = Math.round(Math.log(st.problemSize) / Math.LN2);
    state.k = k;
    document.getElementById('problemSizeInput').value = k;
    document.getElementById('problemSizeVal').value = st.problemSize;
    state.overlay = (st.levelCosts === 'on');
    document.getElementById('levelCostsInput').checked = state.overlay;
    state.active = -1;
    hidePopup();
    document.getElementById('demoNarration').innerHTML = '<b>' + steps[cur].title + '</b><br>' + steps[cur].narration;
    document.getElementById('stepLabel').textContent = cur === 0 ? 'overview' : ('step ' + cur + ' / ' + (steps.length - 1));
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  drawTop();
  applyStep(0);
  window.__markRendered();
})();
